<script setup lang="ts">
import {ref,onMounted,onBeforeUnmount} from 'vue';import {invoke} from '@tauri-apps/api/core';import {listen} from '@tauri-apps/api/event';
interface Row{version:string;size:number;verified:boolean;path:string|null}
const emit=defineEmits<{pick:[path:string]}>();const rows=ref<Row[]>([]),version=ref(''),busy=ref(false),message=ref(''),progress=ref('');let off:(()=>void)|undefined;let mounted=true;const dock=ref(false);const isMac=/Mac/.test(navigator.platform);async function setDock(enabled:boolean){try{dock.value=await invoke<boolean>('numbered_dock',{enabled})}catch(e){message.value=String(e)}}
async function load(refresh=false){try{const list=await invoke<Row[]>('kernel_list',{refresh});rows.value=list;if(!list.some(x=>x.version===version.value))version.value=list[0]?.version??'';message.value=refresh?'已刷新官方版本':''}catch(e){message.value=String(e)}}
const fmt=(n:number)=>n>=1e9?`${(n/1e9).toFixed(2)} GB`:`${(n/1e6).toFixed(1)} MB`;
async function pick(){const row=rows.value.find(x=>x.version===version.value);if(!row||busy.value)return;if(row.path){emit('pick',row.path);return}if(!row.verified)return;busy.value=true;message.value='';progress.value='正在连接…';try{const path=await invoke<string>('kernel_install',{version:row.version});emit('pick',path);await load();message.value='已下载并校验，点保存后生效。'}catch(e){message.value=String(e)}finally{busy.value=false;progress.value=''}}
onMounted(async()=>{await load();if(isMac)dock.value=await invoke<boolean>('numbered_dock',{enabled:null});const cancel=await listen<{stage:string;bytes:number}>('kernel-progress',e=>{progress.value=`${e.payload.stage} · ${fmt(e.payload.bytes)}`});if(!mounted)cancel();else off=cancel});onBeforeUnmount(()=>{mounted=false;off?.()});
</script>
<template><div class="kernel-box"><strong>Camoufox 官方版本</strong><button type="button" class="text-button" :disabled="busy" @click="load(true)">刷新清单</button><div class="kernel-line"><select v-model="version" :disabled="busy" aria-label="选择内核版本"><option v-for="r in rows" :key="r.version" :value="r.version">{{r.version}} · {{r.size?fmt(r.size):'本机'}}{{r.path?' · 已安装':!r.verified?' · 无官方校验值':''}}</option></select><button class="button secondary" type="button" :disabled="busy||!rows.some(r=>r.version===version&&(r.verified||r.path))" @click="pick">{{busy?'处理中…':rows.find(r=>r.version===version)?.path?'选用':'下载并校验'}}</button></div><small>大小为压缩下载量；每个版本仅存一份。切换前关闭星相启动的窗口，旧版优先用新环境试用。</small><label v-if="isMac" style="display:block;margin-top:8px"><input type="checkbox" :checked="dock" @change="setDock(($event.target as HTMLInputElement).checked)"> 显示带环境编号的 Dock 图标（重开环境后生效，系统可能同时显示普通图标）</label><p v-if="progress||message" role="status">{{progress||message}}</p></div></template>
<style scoped>.kernel-box{padding:12px 14px;background:#f5f7fb;border-radius:12px;margin-top:12px;color:#334761}.kernel-box>.text-button{float:right}.kernel-line{display:flex;gap:6px;margin:8px 0}.kernel-line select{min-width:0;flex:1}.kernel-box small,.kernel-box p{font-size:12px}</style>
